// What the office reimburses for one damaged item before the deductible is
// withheld. Absent a special clause, damage is reimbursed in full. (The
// clauses that reduce this -- high enchantment, dragon material -- are looked
// up from the insured item and are not yet needed here.)
function reimbursableAmount(_item: Item | undefined, damage: Damage): number {
  return damage.amount;
}

// The insured item a damage entry refers to, as identified by its type.
function damagedItem(items: Item[], damage: Damage): Item | undefined {
  return items.find((item) => item.type === damage.itemType);
}

// A deductible is withheld per damage event, after the reimbursement clauses
// have decided what the damage is worth.
function damagePayout(items: Item[], damage: Damage): number {
  return reimbursableAmount(damagedItem(items, damage), damage) - DEDUCTIBLE;
}

export function settleClaim(
  items: Item[],
  damages: Damage[],
  remainingCap: number,
): Settlement {
  const payout = damages.reduce(
    (total, damage) => total + damagePayout(items, damage),
    0,
  );
  return { payout, remainingCap: remainingCap - payout };
}

